{"status":"candidate","chosen_option":"prefix_sums","assumptions":["Python 3 is an acceptable implementation language; its integers can represent the sums without fixed-width overflow."],"observations":[{"statement":"The task requires sums for inclusive, one-based ranges, with one result per query.","source_ids":["task"]},{"statement":"The public examples include negative values and expect -5 for a single-element range.","source_ids":["public1"]},{"statement":"The second public example expects -16, -27, -16, -26, -30, and -12 in query order.","source_ids":["public2"]}],"artifact":{"code":"import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, q = data[0], data[1]
    values = data[2:2 + n]

    prefix = [0]
    for value in values:
        prefix.append(prefix[-1] + value)

    out = []
    pos = 2 + n
    for _ in range(q):
        left, right = data[pos], data[pos + 1]
        pos += 2
        out.append(str(prefix[right] - prefix[left - 1]))

    sys.stdout.write('\n'.join(out))
    if out:
        sys.stdout.write('\n')


if __name__ == '__main__':
    main()
